#include <CGAL/Exact_predicates_inexact_constructions_kernel.h>
#include <CGAL/linear_least_squares_fitting_3.h>
#include <list>
#include <stdexcept>

typedef CGAL::Exact_predicates_inexact_constructions_kernel Kernel;
Kernel::Plane_3 compute_best_fitting_plane(const std::list<Kernel::Point_3>& points) {
    if (points.size() < 3) {
        throw std::invalid_argument("At least 3 points are required to compute a best-fitting plane.");
    }
    Kernel::Plane_3 plane;
    if (!CGAL::linear_least_squares_fitting_3(points.begin(), points.end(), plane, CGAL::Dimension_tag<0>())) {
        throw std::runtime_error("Failed to compute the best-fitting plane.");
    }
    return plane;
}

